"use client";

import { useMemo, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  Archive,
  Cloud,
  FileText,
  Folder,
  Grid2x2,
  Image as ImageIcon,
  LayoutDashboard,
  List,
  Music,
  RotateCcw,
  Search,
  Share2,
  Star,
  Trash2,
  Upload,
  Users,
  Video,
  X,
  type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";

type Kind = "document" | "image" | "video" | "audio" | "archive";
type Item = { id: number; name: string; kind: Kind; kb: number; folder: string; modified: string; starred: boolean; trashed: boolean; sharedWith: string[] };
type Page = "overview" | "files" | "shared" | "starred" | "trash" | "team";

const KIND: Record<Kind, { label: string; icon: LucideIcon; tone: string }> = {
  document: { label: "Documents", icon: FileText, tone: "bg-primary" },
  image: { label: "Images", icon: ImageIcon, tone: "bg-primary/70" },
  video: { label: "Video", icon: Video, tone: "bg-primary/45" },
  audio: { label: "Audio", icon: Music, tone: "bg-primary/25" },
  archive: { label: "Archives", icon: Archive, tone: "bg-muted-foreground/40" },
};

const PEOPLE: { name: string; role: string; used: number; uploads: number }[] = [
  { name: "Mara Ellis", role: "Owner", used: 31.4, uploads: 128 },
  { name: "Jonas Reyes", role: "Editor", used: 22.9, uploads: 74 },
  { name: "Priya Nair", role: "Editor", used: 15.2, uploads: 51 },
  { name: "Theo Baptiste", role: "Viewer", used: 6.8, uploads: 12 },
];

const f = (id: number, name: string, kind: Kind, kb: number, folder: string, modified: string, o: Partial<Item> = {}): Item => ({ id, name, kind, kb, folder, modified, starred: false, trashed: false, sharedWith: [], ...o });
const SEED: Item[] = [
  f(1, "Q4 Financial Report.pdf", "document", 2480, "Finance", "2 hours ago", { starred: true, sharedWith: ["Jonas Reyes", "Priya Nair"] }),
  f(2, "Brand Guidelines.pdf", "document", 8120, "Brand", "Yesterday", { sharedWith: ["Priya Nair"] }),
  f(3, "Hero Banner.png", "image", 3340, "Brand", "Yesterday", { starred: true }),
  f(4, "Product Tour.mp4", "video", 184200, "Marketing", "3 days ago", { sharedWith: ["Theo Baptiste"] }),
  f(5, "Roadmap 2026.xlsx", "document", 612, "Product", "3 days ago", { sharedWith: ["Jonas Reyes"] }),
  f(6, "Podcast Intro.wav", "audio", 24800, "Marketing", "Last week"),
  f(7, "Team Photos.zip", "archive", 96400, "People", "Last week"),
  f(8, "Logo Pack.zip", "archive", 12400, "Brand", "2 weeks ago", { starred: true }),
  f(9, "Meeting Notes.txt", "document", 14, "Product", "2 weeks ago"),
  f(10, "Landing Mockup.png", "image", 5210, "Design", "2 weeks ago", { sharedWith: ["Priya Nair", "Theo Baptiste"] }),
  f(11, "Old Backup.zip", "archive", 220400, "Archive", "Last month", { trashed: true }),
  f(12, "Draft Pitch.pdf", "document", 1830, "Finance", "Last month", { trashed: true }),
];

const FOLDERS = [
  { name: "Brand", color: "bg-primary/15 text-primary" },
  { name: "Marketing", color: "bg-accent text-accent-foreground" },
  { name: "Product", color: "bg-muted text-foreground" },
  { name: "Finance", color: "bg-primary/15 text-primary" },
];

const ACTIVITY = [
  { who: "Jonas Reyes", what: "uploaded", obj: "Hero Banner.png", when: "2h ago" },
  { who: "Priya Nair", what: "shared", obj: "Brand Guidelines.pdf", when: "Yesterday" },
  { who: "You", what: "starred", obj: "Q4 Financial Report.pdf", when: "Yesterday" },
  { who: "Theo Baptiste", what: "commented on", obj: "Product Tour.mp4", when: "3 days ago" },
  { who: "You", what: "removed", obj: "Old Backup.zip", when: "Last month" },
];

const size = (kb: number) => (kb < 1024 ? `${kb} KB` : kb < 1024 * 1024 ? `${(kb / 1024).toFixed(1)} MB` : `${(kb / 1024 / 1024).toFixed(1)} GB`);
const initials = (n: string) => n.split(" ").map((p) => p[0]).join("");
const TOTAL_GB = 100;

function Avatar({ name, className }: { name: string; className?: string }) {
  return <span title={name} className={cn("grid size-7 place-items-center rounded-full border-2 border-card bg-muted text-[10px] font-medium", className)}>{initials(name)}</span>;
}

function Donut({ parts, used }: { parts: { kind: Kind; gb: number }[]; used: number }) {
  const r = 52;
  const c = 2 * Math.PI * r;
  const offsets = parts.map((_, i) => parts.slice(0, i).reduce((a, x) => a + (x.gb / TOTAL_GB) * c, 0));
  const tones = ["stroke-primary", "stroke-primary/70", "stroke-primary/45", "stroke-primary/25", "stroke-muted-foreground/40"];
  return (
    <div className="relative size-44 shrink-0">
      <svg viewBox="0 0 120 120" className="size-full -rotate-90" aria-hidden>
        <circle cx="60" cy="60" r={r} fill="none" strokeWidth="11" className="stroke-muted" />
        {parts.map((p, i) => {
          const len = (p.gb / TOTAL_GB) * c;
          return (
            <motion.circle
              key={p.kind}
              cx="60"
              cy="60"
              r={r}
              fill="none"
              strokeWidth="11"
              strokeLinecap="butt"
              className={tones[i]}
              strokeDasharray={`${Math.max(0, len - 1.5)} ${c}`}
              strokeDashoffset={-offsets[i]}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.1 * i, duration: 0.6 }}
            />
          );
        })}
      </svg>
      <div className="absolute inset-0 grid place-items-center text-center">
        <div>
          <p className="text-3xl font-semibold tracking-tight">{used.toFixed(1)}</p>
          <p className="text-xs text-muted-foreground">of {TOTAL_GB} GB used</p>
        </div>
      </div>
    </div>
  );
}

function Card({ title, action, children, className }: { title: string; action?: ReactNode; children: ReactNode; className?: string }) {
  return (
    <section className={cn("rounded-2xl border bg-card p-5", className)}>
      <div className="mb-4 flex items-center justify-between gap-3">
        <h2 className="text-sm font-semibold tracking-tight">{title}</h2>
        {action}
      </div>
      {children}
    </section>
  );
}

function Row({ item, onStar, onTrash, selected, onSelect }: { item: Item; onStar: () => void; onTrash: () => void; selected?: boolean; onSelect?: () => void }) {
  const K = KIND[item.kind];
  return (
    <tr className={cn("group border-b last:border-0 transition-colors hover:bg-accent/50", selected && "bg-accent/60")}>
      {onSelect && (
        <td className="w-10 pl-4">
          <input type="checkbox" aria-label={`Select ${item.name}`} checked={!!selected} onChange={onSelect} className="size-4 accent-[var(--primary)]" />
        </td>
      )}
      <td className="py-3 pl-4">
        <div className="flex items-center gap-3">
          <span className="grid size-9 shrink-0 place-items-center rounded-lg bg-muted"><K.icon className="size-4" /></span>
          <div className="min-w-0">
            <p className="truncate text-sm font-medium">{item.name}</p>
            <p className="text-xs text-muted-foreground sm:hidden">{size(item.kb)}</p>
          </div>
        </div>
      </td>
      <td className="hidden px-3 text-sm text-muted-foreground md:table-cell">{item.folder}</td>
      <td className="hidden px-3 text-sm text-muted-foreground sm:table-cell">{size(item.kb)}</td>
      <td className="hidden px-3 text-sm text-muted-foreground lg:table-cell">{item.modified}</td>
      <td className="pr-3 text-right">
        <span className="inline-flex gap-0.5">
          <button type="button" aria-label={item.starred ? "Unstar" : "Star"} onClick={onStar} className="grid size-8 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
            <Star className={cn("size-4", item.starred && "fill-primary text-primary")} />
          </button>
          <button type="button" aria-label="Move to trash" onClick={onTrash} className="grid size-8 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
            <Trash2 className="size-4" />
          </button>
        </span>
      </td>
    </tr>
  );
}

/**
 * A file manager dashboard with six pages: overview, files, shared, starred, trash and team. Search,
 * filters, sorting, a list or grid view, starring, sharing, bulk trash, restore and a simulated upload
 * all work on local state. Replace the state with your own storage calls.
 */
export function FileManagerTemplate({ name = "Vault", className }: { name?: string; className?: string }) {
  const [items, setItems] = useState<Item[]>(SEED);
  const [page, setPage] = useState<Page>("overview");
  const [q, setQ] = useState("");
  const [kind, setKind] = useState<Kind | "all">("all");
  const [sort, setSort] = useState<"modified" | "name" | "size">("modified");
  const [grid, setGrid] = useState(false);
  const [picked, setPicked] = useState<number[]>([]);
  const [toast, setToast] = useState("");
  const next = useRef(100);

  const live = items.filter((i) => !i.trashed);
  const trashed = items.filter((i) => i.trashed);
  const usedGb = 78.4;
  const parts = useMemo(() => {
    const base: Record<Kind, number> = { document: 21.6, image: 18.9, video: 29.8, audio: 5.4, archive: 2.7 };
    return (Object.keys(base) as Kind[]).map((k) => ({ kind: k, gb: base[k] }));
  }, []);

  const say = (t: string) => {
    setToast(t);
    window.setTimeout(() => setToast(""), 2200);
  };
  const patch = (id: number, p: Partial<Item>) => setItems((cur) => cur.map((i) => (i.id === id ? { ...i, ...p } : i)));
  const trash = (id: number) => { patch(id, { trashed: true }); setPicked((s) => s.filter((x) => x !== id)); say("Moved to trash"); };

  const list = useMemo(() => {
    const term = q.trim().toLowerCase();
    let l = live.filter((i) => (kind === "all" || i.kind === kind) && (!term || i.name.toLowerCase().includes(term)));
    if (page === "shared") l = l.filter((i) => i.sharedWith.length);
    if (page === "starred") l = l.filter((i) => i.starred);
    const order = ["2 hours ago", "Yesterday", "3 days ago", "Last week", "2 weeks ago", "Last month"];
    return [...l].sort((a, b) => (sort === "name" ? a.name.localeCompare(b.name) : sort === "size" ? b.kb - a.kb : order.indexOf(a.modified) - order.indexOf(b.modified)));
  }, [live, q, kind, sort, page]);

  const upload = () => {
    const id = next.current++;
    setItems((cur) => [f(id, `Upload ${id - 99}.pdf`, "document", 1240, "Inbox", "Just now"), ...cur]);
    say("Uploaded 1 file");
  };

  const nav: { id: Page; label: string; icon: LucideIcon; count?: number }[] = [
    { id: "overview", label: "Overview", icon: LayoutDashboard },
    { id: "files", label: "My files", icon: Folder, count: live.length },
    { id: "shared", label: "Shared", icon: Share2, count: live.filter((i) => i.sharedWith.length).length },
    { id: "starred", label: "Starred", icon: Star, count: live.filter((i) => i.starred).length },
    { id: "trash", label: "Trash", icon: Trash2, count: trashed.length },
    { id: "team", label: "Team", icon: Users },
  ];
  const titles: Record<Page, string> = { overview: "Overview", files: "My files", shared: "Shared with people", starred: "Starred", trash: "Trash", team: "Team" };

  const Toolbar = (
    <div className="mb-4 flex flex-wrap items-center gap-2">
      <div role="tablist" aria-label="Type" className="flex flex-wrap gap-1">
        {(["all", "document", "image", "video", "audio", "archive"] as const).map((k) => (
          <button key={k} role="tab" aria-selected={kind === k} onClick={() => setKind(k)} className={cn("rounded-full border px-3 py-1 text-xs transition-colors", kind === k ? "border-primary bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground")}>
            {k === "all" ? "All" : KIND[k].label}
          </button>
        ))}
      </div>
      <div className="ml-auto flex items-center gap-2">
        <select aria-label="Sort" value={sort} onChange={(e) => setSort(e.target.value as typeof sort)} className="h-8 rounded-lg border bg-card px-2 text-xs outline-none">
          <option value="modified">Newest</option>
          <option value="name">Name</option>
          <option value="size">Size</option>
        </select>
        <div className="flex rounded-lg border bg-card p-0.5">
          {[{ g: false, i: List, l: "List" }, { g: true, i: Grid2x2, l: "Grid" }].map(({ g, i: I, l }) => (
            <button key={l} type="button" aria-label={`${l} view`} aria-pressed={grid === g} onClick={() => setGrid(g)} className={cn("grid size-7 place-items-center rounded-md transition-colors", grid === g ? "bg-accent text-foreground" : "text-muted-foreground")}>
              <I className="size-3.5" />
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  const Files = (
    <>
      {Toolbar}
      <AnimatePresence>
        {picked.length > 0 && (
          <motion.div initial={{ opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mb-3 flex items-center gap-3 rounded-xl border bg-card px-4 py-2 text-sm">
            {picked.length} selected
            <button type="button" onClick={() => { picked.forEach(trash); setPicked([]); }} className="ml-auto inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-xs transition-colors hover:bg-accent"><Trash2 className="size-3.5" /> Trash</button>
            <button type="button" aria-label="Clear selection" onClick={() => setPicked([])} className="grid size-6 place-items-center rounded-md hover:bg-accent"><X className="size-3.5" /></button>
          </motion.div>
        )}
      </AnimatePresence>
      {list.length === 0 ? (
        <div className="grid place-items-center rounded-2xl border border-dashed py-16 text-center">
          <div>
            <p className="font-medium">Nothing here</p>
            <p className="mt-1 text-sm text-muted-foreground">Try another filter, or upload something.</p>
          </div>
        </div>
      ) : grid ? (
        <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {list.map((i) => {
            const K = KIND[i.kind];
            return (
              <li key={i.id} className="group relative rounded-2xl border bg-card p-4 transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/40">
                <span className="grid h-20 place-items-center rounded-xl bg-muted"><K.icon className="size-7 text-muted-foreground" /></span>
                <p className="mt-3 truncate text-sm font-medium">{i.name}</p>
                <p className="text-xs text-muted-foreground">{size(i.kb)} · {i.modified}</p>
                <button type="button" aria-label="Star" onClick={() => patch(i.id, { starred: !i.starred })} className="absolute right-3 top-3 grid size-7 place-items-center rounded-lg bg-card/80 backdrop-blur"><Star className={cn("size-3.5", i.starred && "fill-primary text-primary")} /></button>
              </li>
            );
          })}
        </ul>
      ) : (
        <div className="overflow-hidden rounded-2xl border bg-card">
          <table className="w-full text-left">
            <thead className="border-b text-xs text-muted-foreground">
              <tr>
                <th className="w-10 pl-4" />
                <th className="py-3 pl-4 font-medium">Name</th>
                <th className="hidden px-3 font-medium md:table-cell">Folder</th>
                <th className="hidden px-3 font-medium sm:table-cell">Size</th>
                <th className="hidden px-3 font-medium lg:table-cell">Modified</th>
                <th />
              </tr>
            </thead>
            <tbody>
              {list.map((i) => (
                <Row key={i.id} item={i} selected={picked.includes(i.id)} onSelect={() => setPicked((s) => (s.includes(i.id) ? s.filter((x) => x !== i.id) : [...s, i.id]))} onStar={() => patch(i.id, { starred: !i.starred })} onTrash={() => trash(i.id)} />
              ))}
            </tbody>
          </table>
        </div>
      )}
    </>
  );

  const Overview = (
    <div className="grid gap-4 xl:grid-cols-3">
      <Card title="Storage" className="xl:col-span-2">
        <div className="flex flex-col items-center gap-6 sm:flex-row">
          <Donut parts={parts} used={usedGb} />
          <ul className="grid w-full flex-1 grid-cols-2 gap-3">
            {parts.map((p) => {
              const K = KIND[p.kind];
              return (
                <li key={p.kind} className="rounded-xl border p-3">
                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <span className={cn("size-2 rounded-full", K.tone)} /> {K.label}
                  </div>
                  <p className="mt-1.5 text-lg font-semibold tracking-tight">{p.gb} GB</p>
                </li>
              );
            })}
            <li className="rounded-xl border border-dashed p-3">
              <p className="text-xs text-muted-foreground">Free</p>
              <p className="mt-1.5 text-lg font-semibold tracking-tight">{(TOTAL_GB - usedGb).toFixed(1)} GB</p>
            </li>
          </ul>
        </div>
      </Card>

      <Card title="Recent activity">
        <ul className="space-y-4">
          {ACTIVITY.map((a, i) => (
            <li key={i} className="flex gap-3 text-sm">
              <Avatar name={a.who === "You" ? "Mara Ellis" : a.who} className="mt-0.5 shrink-0" />
              <p className="min-w-0 text-muted-foreground">
                <span className="text-foreground">{a.who}</span> {a.what} <span className="text-foreground">{a.obj}</span>
                <span className="block text-xs">{a.when}</span>
              </p>
            </li>
          ))}
        </ul>
      </Card>

      <Card title="Quick access" className="xl:col-span-3">
        <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          {FOLDERS.map((fo) => {
            const n = live.filter((i) => i.folder === fo.name).length;
            return (
              <li key={fo.name}>
                <button type="button" onClick={() => { setPage("files"); setQ(""); }} className="group flex w-full items-center gap-3 rounded-xl border p-3.5 text-left transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/40">
                  <span className={cn("grid size-10 place-items-center rounded-lg", fo.color)}><Folder className="size-[18px]" /></span>
                  <span>
                    <span className="block text-sm font-medium">{fo.name}</span>
                    <span className="block text-xs text-muted-foreground">{n} files</span>
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      </Card>

      <Card title="Recent files" className="xl:col-span-3" action={<button type="button" onClick={() => setPage("files")} className="text-xs text-muted-foreground transition-colors hover:text-foreground">View all</button>}>
        <div className="-mx-5 -mb-5 overflow-hidden rounded-b-2xl">
          <table className="w-full text-left">
            <tbody>
              {live.slice(0, 5).map((i) => (
                <Row key={i.id} item={i} onStar={() => patch(i.id, { starred: !i.starred })} onTrash={() => trash(i.id)} />
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );

  const Team = (
    <div className="space-y-4">
      <Card title="Storage by member">
        <ul className="space-y-5">
          {PEOPLE.map((p) => (
            <li key={p.name} className="flex items-center gap-4">
              <Avatar name={p.name} className="size-9 text-xs" />
              <div className="min-w-0 flex-1">
                <div className="flex items-baseline justify-between gap-3">
                  <p className="truncate text-sm font-medium">{p.name} <span className="ml-1 text-xs font-normal text-muted-foreground">{p.role}</span></p>
                  <p className="shrink-0 text-xs text-muted-foreground">{p.used} GB · {p.uploads} uploads</p>
                </div>
                <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted">
                  <motion.div className="h-full rounded-full bg-primary" initial={{ width: 0 }} animate={{ width: `${(p.used / 35) * 100}%` }} transition={{ duration: 0.9, ease: [0.32, 0.72, 0, 1] }} />
                </div>
              </div>
            </li>
          ))}
        </ul>
      </Card>
      <Card title="Invite someone" action={<span className="text-xs text-muted-foreground">4 of 10 seats used</span>}>
        <form onSubmit={(e) => { e.preventDefault(); say("Invite sent"); }} className="flex gap-2">
          <input required type="email" placeholder="name@company.com" className="h-10 min-w-0 flex-1 rounded-xl border bg-background px-3 text-sm outline-none focus:ring-4 focus:ring-ring/15" />
          <button type="submit" className="h-10 rounded-xl bg-primary px-4 text-sm font-medium text-primary-foreground transition-opacity hover:opacity-90">Send invite</button>
        </form>
      </Card>
    </div>
  );

  const Shared = (
    <>
      {Toolbar}
      <ul className="divide-y rounded-2xl border bg-card">
        {list.map((i) => {
          const K = KIND[i.kind];
          return (
            <li key={i.id} className="flex items-center gap-4 p-4">
              <span className="grid size-10 shrink-0 place-items-center rounded-xl bg-muted"><K.icon className="size-4" /></span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium">{i.name}</p>
                <p className="text-xs text-muted-foreground">{size(i.kb)} · {i.modified}</p>
              </div>
              <div className="flex -space-x-2">{i.sharedWith.map((n) => <Avatar key={n} name={n} />)}</div>
              <button type="button" onClick={() => patch(i.id, { sharedWith: [] })} className="rounded-lg border px-3 py-1.5 text-xs transition-colors hover:bg-accent">Stop sharing</button>
            </li>
          );
        })}
        {list.length === 0 && <li className="p-10 text-center text-sm text-muted-foreground">Nothing is shared.</li>}
      </ul>
    </>
  );

  const Trash = (
    <>
      <div className="mb-4 flex items-center justify-between">
        <p className="text-sm text-muted-foreground">Items here are removed for good after 30 days.</p>
        <button type="button" disabled={!trashed.length} onClick={() => { setItems((c) => c.filter((i) => !i.trashed)); say("Trash emptied"); }} className="rounded-lg border px-3 py-1.5 text-xs transition-colors hover:bg-accent disabled:opacity-40">Empty trash</button>
      </div>
      <ul className="divide-y rounded-2xl border bg-card">
        {trashed.map((i) => {
          const K = KIND[i.kind];
          return (
            <li key={i.id} className="flex items-center gap-4 p-4">
              <span className="grid size-10 shrink-0 place-items-center rounded-xl bg-muted"><K.icon className="size-4" /></span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium">{i.name}</p>
                <p className="text-xs text-muted-foreground">{size(i.kb)}</p>
              </div>
              <button type="button" onClick={() => { patch(i.id, { trashed: false }); say("Restored"); }} className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs transition-colors hover:bg-accent"><RotateCcw className="size-3.5" /> Restore</button>
              <button type="button" aria-label="Delete forever" onClick={() => setItems((c) => c.filter((x) => x.id !== i.id))} className="grid size-8 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"><X className="size-4" /></button>
            </li>
          );
        })}
        {!trashed.length && <li className="p-10 text-center text-sm text-muted-foreground">Trash is empty.</li>}
      </ul>
    </>
  );

  return (
    <div className={cn("flex h-full min-h-[34rem] w-full overflow-hidden bg-background text-foreground", className)}>
      <aside className="hidden w-60 shrink-0 flex-col border-r bg-card/50 p-4 lg:flex">
        <div className="flex items-center gap-2.5 px-2 pb-6 pt-1">
          <span className="grid size-8 place-items-center rounded-lg bg-primary text-primary-foreground"><Cloud className="size-4" /></span>
          <p className="font-semibold tracking-tight">{name}</p>
        </div>
        <nav aria-label="Pages" className="space-y-0.5">
          {nav.map(({ id, label, icon: Icon, count }) => (
            <button key={id} type="button" aria-current={page === id} onClick={() => setPage(id)} className={cn("flex w-full items-center gap-3 rounded-lg px-3 py-2 text-sm transition-colors", page === id ? "bg-accent font-medium text-foreground" : "text-muted-foreground hover:bg-accent/60 hover:text-foreground")}>
              <Icon className="size-4" />
              {label}
              {count !== undefined && <span className="ml-auto text-xs tabular-nums text-muted-foreground">{count}</span>}
            </button>
          ))}
        </nav>
        <div className="mt-auto rounded-2xl border bg-card p-4">
          <p className="text-sm font-medium">{usedGb} of {TOTAL_GB} GB</p>
          <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${usedGb}%` }} /></div>
          <button type="button" className="mt-3 w-full rounded-lg bg-foreground py-2 text-xs font-medium text-background transition-opacity hover:opacity-85">Upgrade storage</button>
        </div>
      </aside>

      <div className="relative flex min-w-0 flex-1 flex-col">
        <header className="flex h-16 shrink-0 items-center gap-3 border-b px-5">
          <label className="flex h-10 min-w-0 max-w-sm flex-1 items-center gap-2 rounded-xl bg-muted px-3 text-sm text-muted-foreground focus-within:ring-2 focus-within:ring-ring/30">
            <Search className="size-4 shrink-0" />
            <input value={q} onChange={(e) => { setQ(e.target.value); if (page === "overview") setPage("files"); }} placeholder="Search files" className="w-full bg-transparent text-foreground outline-none placeholder:text-muted-foreground" />
          </label>
          <button type="button" onClick={upload} className="ml-auto inline-flex h-10 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-medium text-primary-foreground transition-all duration-300 hover:opacity-90 active:scale-[0.97]">
            <Upload className="size-4" /> <span className="hidden sm:inline">Upload</span>
          </button>
        </header>

        <div className="relative min-h-0 flex-1 overflow-y-auto p-5">
          {/* compact page switcher for narrow stages */}
          <div role="tablist" aria-label="Pages" className="mb-4 flex gap-1 overflow-x-auto lg:hidden">
            {nav.map(({ id, label }) => (
              <button key={id} role="tab" aria-selected={page === id} onClick={() => setPage(id)} className={cn("shrink-0 rounded-full border px-3 py-1 text-xs", page === id ? "border-primary bg-primary text-primary-foreground" : "text-muted-foreground")}>{label}</button>
            ))}
          </div>
          <div className="mb-5 flex items-center gap-2">
            <h1 className="text-xl font-semibold tracking-tight">{titles[page]}</h1>
            {page !== "overview" && page !== "team" && page !== "trash" && <span className="text-sm text-muted-foreground">{list.length}</span>}
          </div>
          <AnimatePresence mode="wait" initial={false}>
            <motion.div key={page} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -6 }} transition={{ duration: 0.25, ease: [0.32, 0.72, 0, 1] }}>
              {page === "overview" && Overview}
              {(page === "files" || page === "starred") && Files}
              {page === "shared" && Shared}
              {page === "trash" && Trash}
              {page === "team" && Team}
            </motion.div>
          </AnimatePresence>
        </div>

        <AnimatePresence>
          {toast && (
            <motion.p initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 12 }} role="status" className="absolute bottom-5 left-1/2 z-20 -translate-x-1/2 rounded-full bg-foreground px-4 py-2 text-sm text-background shadow-lg">
              {toast}
            </motion.p>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

